<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal(); require_first_access_clear(); $pageTitle='Usuários da Livraria'; $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($action==='toggle'){$pdo->prepare('UPDATE usuarios SET ativo=CASE ativo WHEN 1 THEN 0 ELSE 1 END, atualizado_em=? WHERE id=?')->execute([now(),$id]);log_action('alteração de usuário','usuarios',$id);flash('success','Status do usuário atualizado.');redirect('index.php');}}
$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT * FROM usuarios WHERE nome LIKE ? OR login LIKE ? OR email LIKE ? ORDER BY ativo DESC,nome');$x='%'.$q.'%';$st->execute([$x,$x,$x]);$rows=$st->fetchAll();include __DIR__.'/../../includes/header.php'; ?>
<div class="page-head"><div><h1>Usuários da Livraria</h1><div class="muted">Todos os usuários internos possuem o mesmo acesso.</div></div><div class="actions"><a class="btn primary" href="form.php">＋ Novo usuário</a><a class="btn secondary" href="alterar-senha.php">Alterar minha senha</a></div></div>
<div class="card"><form class="search-row" method="get"><input name="q" value="<?=e($q)?>" placeholder="Pesquisar por nome, login ou e-mail"><button class="btn secondary">Pesquisar</button></form></div>
<div class="card" style="margin-top:16px"><div class="table-wrap"><table class="table"><thead><tr><th>Nome</th><th>Login</th><th>E-mail</th><th>Status</th><th>Criado</th><th>Ações</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['nome'])?></td><td><?=e($r['login'])?></td><td><?=e($r['email'])?></td><td><?=status_badge($r['ativo']?'Ativo':'Inativo')?></td><td><?=date_br($r['criado_em'])?></td><td class="nowrap"><a class="btn small secondary" href="form.php?id=<?=$r['id']?>">Editar</a> <form style="display:inline" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="action" value="toggle"><button class="btn small <?= $r['ativo']?'danger':'secondary'?>" onclick="return confirmAction('Alterar status deste usuário?')"><?=$r['ativo']?'Desativar':'Reativar'?></button></form></td></tr><?php endforeach; if(!$rows): ?><tr><td colspan="6" class="empty">Nenhum usuário encontrado.</td></tr><?php endif;?></tbody></table></div></div>
<?php include __DIR__.'/../../includes/footer.php'; ?>
